CREATE PROCEDURE dbo.O7DWETLDM_PURGEDATAWAREHOUSE	    @tN_runNumber numeric(18,0),
						    @tS_tenantID           nvarchar(50),
						    @tS_loadFlag           nvarchar(1),   /* r5dwetlrunctrl.run_loadFlag%TYPE, */
						    @tS_loadType           nvarchar(255),
						    @tD_loadFromDate       datetime,
						    @tD_loadToDate         datetime,
						    @tD_nextStartDate      datetime,
						    @tD_minWarehouseDate   datetime,
						    @tS_purgeFlag          nvarchar(1),   /*r5dwetlrunctrl.run_purgeflag%TYPE, */
						    @tD_purgeToDate        datetime,
						    @tS_defaultLanguage    nvarchar(2),   /* r5languages.lan_code%TYPE, */
						    @tS_defaultCurrency    nvarchar(200),   /* r5install.ins_desc%TYPE, */
						    @tS_oldDefaultCurrency nvarchar(3),   /* r5dwetlrunctrl.run_defcur%TYPE, */
						    @tB_debug              bit,
						    @tB_isRepair           bit,
						    @tD_originalLoadFromDate datetime,
						    @tD_originalLoadToDate datetime,
						    @tB_hasObjectType2SCDChanges bit,
						    @tB_hasSupplierType2SCDChanges bit,
						    @tD_loadFirstDate      datetime
AS
SET NOCOUNT ON
declare @nReturn    int

    begin

    	execute @nReturn = O7DWETLDM_PURGEAVAILLABORDAILYSNAP	   @tN_runNumber ,
    								   @tS_tenantID           ,
    								   @tS_loadFlag           ,   
    								   @tS_loadType           ,
    								   @tD_loadFromDate       ,
    								   @tD_loadToDate         ,
    								   @tD_nextStartDate      ,
    								   @tD_minWarehouseDate   ,
    								   @tS_purgeFlag          ,   
    								   @tD_purgeToDate        ,
    								   @tS_defaultLanguage    ,   
    								   @tS_defaultCurrency    ,   
    								   @tS_oldDefaultCurrency ,   
    								   @tB_debug              ,
    								   @tB_isRepair           ,
    								   @tD_originalLoadFromDate,
    								   @tD_originalLoadToDate,
    								   @tB_hasObjectType2SCDChanges,
    								   @tB_hasSupplierType2SCDChanges,
    								   @tD_loadFirstDate 
    	if @@ERROR <> 0 OR @nReturn <> 0
    	return -1             

    	execute @nReturn = O7DWETLDM_PURGELABORDAILYSNAPSHOT	   @tN_runNumber ,
    								   @tS_tenantID           ,
    								   @tS_loadFlag           ,   
    								   @tS_loadType           ,
    								   @tD_loadFromDate       ,
    								   @tD_loadToDate         ,
    								   @tD_nextStartDate      ,
    								   @tD_minWarehouseDate   ,
    								   @tS_purgeFlag          ,   
    								   @tD_purgeToDate        ,
    								   @tS_defaultLanguage    ,   
    								   @tS_defaultCurrency    ,   
    								   @tS_oldDefaultCurrency ,   
    								   @tB_debug              ,
    								   @tB_isRepair           ,
    								   @tD_originalLoadFromDate,
    								   @tD_originalLoadToDate,
    								   @tB_hasObjectType2SCDChanges,
    								   @tB_hasSupplierType2SCDChanges,
    								   @tD_loadFirstDate 
    	if @@ERROR <> 0 OR @nReturn <> 0
    	return -1      

    	execute @nReturn = O7DWETLDM_PURGEMATERIALTRANSDAILYSNAP   @tN_runNumber ,
    								   @tS_tenantID           ,
    								   @tS_loadFlag           ,   
    								   @tS_loadType           ,
    								   @tD_loadFromDate       ,
    								   @tD_loadToDate         ,
    								   @tD_nextStartDate      ,
    								   @tD_minWarehouseDate   ,
    								   @tS_purgeFlag          ,   
    								   @tD_purgeToDate        ,
    								   @tS_defaultLanguage    ,   
    								   @tS_defaultCurrency    ,   
    								   @tS_oldDefaultCurrency ,   
    								   @tB_debug              ,
    								   @tB_isRepair           ,
    								   @tD_originalLoadFromDate,
    								   @tD_originalLoadToDate,
    								   @tB_hasObjectType2SCDChanges,
    								   @tB_hasSupplierType2SCDChanges,
    								   @tD_loadFirstDate 
    	if @@ERROR <> 0 OR @nReturn <> 0
    	return -1 

    	execute @nReturn = O7DWETLDM_PURGESTORESDAILYSNAPSHOT      @tN_runNumber ,
    								   @tS_tenantID           ,
    								   @tS_loadFlag           ,   
    								   @tS_loadType           ,
    								   @tD_loadFromDate       ,
    								   @tD_loadToDate         ,
    								   @tD_nextStartDate      ,
    								   @tD_minWarehouseDate   ,
    								   @tS_purgeFlag          ,   
    								   @tD_purgeToDate        ,
    								   @tS_defaultLanguage    ,   
    								   @tS_defaultCurrency    ,   
    								   @tS_oldDefaultCurrency ,   
    								   @tB_debug              ,
    								   @tB_isRepair           ,
    								   @tD_originalLoadFromDate,
    								   @tD_originalLoadToDate,
    								   @tB_hasObjectType2SCDChanges,
    								   @tB_hasSupplierType2SCDChanges,
    								   @tD_loadFirstDate 
    	if @@ERROR <> 0 OR @nReturn <> 0
    	return -1

    	execute @nReturn = O7DWETLDM_PURGEPARTSDAILYSNAPSHOT       @tN_runNumber ,
    								   @tS_tenantID           ,
    								   @tS_loadFlag           ,   
    								   @tS_loadType           ,
    								   @tD_loadFromDate       ,
    								   @tD_loadToDate         ,
    								   @tD_nextStartDate      ,
    								   @tD_minWarehouseDate   ,
    								   @tS_purgeFlag          ,   
    								   @tD_purgeToDate        ,
    								   @tS_defaultLanguage    ,   
    								   @tS_defaultCurrency    ,   
    								   @tS_oldDefaultCurrency ,   
    								   @tB_debug              ,
    								   @tB_isRepair           ,
    								   @tD_originalLoadFromDate,
    								   @tD_originalLoadToDate,
    								   @tB_hasObjectType2SCDChanges,
    								   @tB_hasSupplierType2SCDChanges,
    								   @tD_loadFirstDate 
    	if @@ERROR <> 0 OR @nReturn <> 0
    	return -1

    	execute @nReturn = O7DWETLDM_PURGEPARTSTRANSDAILYSNAP      @tN_runNumber ,
    								   @tS_tenantID           ,
    								   @tS_loadFlag           ,   
    								   @tS_loadType           ,
    								   @tD_loadFromDate       ,
    								   @tD_loadToDate         ,
    								   @tD_nextStartDate      ,
    								   @tD_minWarehouseDate   ,
    								   @tS_purgeFlag          ,   
    								   @tD_purgeToDate        ,
    								   @tS_defaultLanguage    ,   
    								   @tS_defaultCurrency    ,   
    								   @tS_oldDefaultCurrency ,   
    								   @tB_debug              ,
    								   @tB_isRepair           ,
    								   @tD_originalLoadFromDate,
    								   @tD_originalLoadToDate,
    								   @tB_hasObjectType2SCDChanges,
    								   @tB_hasSupplierType2SCDChanges,
    								   @tD_loadFirstDate 
    	if @@ERROR <> 0 OR @nReturn <> 0
    	return -1    

    	execute @nReturn = O7DWETLDM_PURGESTATUSDAILYSNAPSHOT      @tN_runNumber ,
    								   @tS_tenantID           ,
    								   @tS_loadFlag           ,   
    								   @tS_loadType           ,
    								   @tD_loadFromDate       ,
    								   @tD_loadToDate         ,
    								   @tD_nextStartDate      ,
    								   @tD_minWarehouseDate   ,
    								   @tS_purgeFlag          ,   
    								   @tD_purgeToDate        ,
    								   @tS_defaultLanguage    ,   
    								   @tS_defaultCurrency    ,   
    								   @tS_oldDefaultCurrency ,   
    								   @tB_debug              ,
    								   @tB_isRepair           ,
    								   @tD_originalLoadFromDate,
    								   @tD_originalLoadToDate,
    								   @tB_hasObjectType2SCDChanges,
    								   @tB_hasSupplierType2SCDChanges,
    								   @tD_loadFirstDate 
