CREATE PROCEDURE dbo.O7DWETLDM_REVERSETRANSACTION @rSTransaction_tra_code             nvarchar(30), -- r5transactions.tra_code%TYPE,
					  @rNTransaction_trl_line             numeric(8,0), --r5translines.trl_line%TYPE,
					  @rSTransaction_tra_rtype            nvarchar(4), --r5transactions.tra_rtype%TYPE,
					  @rSTransaction_tra_fromrentity      nvarchar(4), --r5transactions.tra_fromrentity%TYPE,
					  @rSTransaction_tra_torentity        nvarchar(4), --r5transactions.tra_torentity%TYPE,
					  @rSTransaction_tra_fromcode         nvarchar(30), --r5transactions.tra_fromcode%TYPE,					
					  @rSTransaction_trl_rtype            nvarchar(4), --r5translines.trl_rtype%TYPE,
					  @rDTransaction_trl_date             datetime,    --r5translines.trl_date%TYPE,
					  @rSTransaction_trl_store            nvarchar(15), --r5translines.trl_store%TYPE,
					  @rSTransaction_str_org              nvarchar(15),  --r5stores.str_org%TYPE,
					  @rSTransaction_trl_part             nvarchar(30), --r5translines.trl_part%TYPE,
					  @rSTransaction_trl_part_org         nvarchar(30), --r5translines.trl_part_org%TYPE,
					  @rNTransaction_trl_price            numeric(24,6), --r5translines.trl_price%TYPE,
					  @rNTransaction_trl_qty              numeric(24,6), --r5translines.trl_qty%TYPE,
					  @rNTransaction_trl_scrapqty         numeric(24,6), --r5translines.trl_scrapqty%TYPE,
					  @rNTransaction_trl_io               numeric(18,0), --r5translines.trl_io%TYPE,
					  @rSTransaction_trl_event            nvarchar(30),   --r5translines.trl_event%TYPE,
					  @rSTransaction_trl_order            nvarchar(30),  --r5translines.trl_order%TYPE,
					  @rSTransaction_orl_rtype            nvarchar(4),   --r5orderlines.orl_rtype%TYPE,
					  @rSTransaction_orl_rtype2           nvarchar(4),   --r5orderlines.orl_rtype%TYPE,
					  @rNTransaction_orl_contractdiscount numeric(24,6),  --number,
					  @rNTransaction_orl_totextracost     numeric(24,6),  --number,
					  @rNTransaction_orl_tottaxcost       numeric(24,6),  --number,
					  @rSTransaction_sto_pricetype        nvarchar(4), @bDebug bit
AS
SET NOCOUNT ON
SET IMPLICIT_TRANSACTIONS OFF
declare @rSPart_ztp_part  			nvarchar(30), -- r5dwtmpparts.ztp_part%TYPE,
@rSPart_ztp_partorg                 nvarchar(15), -- r5dwtmpparts.ztp_partorg%TYPE,
@rSPart_ztp_store                   nvarchar(15), -- r5dwtmpparts.ztp_store%TYPE,
@rSPart_ztp_storeorg                nvarchar(15), -- r5dwtmpparts.ztp_storeorg%TYPE,
@rSPart_ztp_partclass               nvarchar(8),  -- r5dwtmpparts.ztp_partclass%TYPE,
@rSPart_ztp_partclassorg            nvarchar(15), -- r5dwtmpparts.ztp_partclassorg%TYPE,
@rNPart_ztp_qtyonhand               numeric(24,6),-- r5dwtmpparts.ztp_qtyonhand%TYPE,
@rNPart_ztp_qtytorepair             numeric(24,6),-- r5dwtmpparts.ztp_qtytorepair%TYPE,
@rNPart_ztp_qtyintransit            numeric(24,6),-- r5dwtmpparts.ztp_qtyintransit%TYPE,
@rNPart_ztp_qtytorepairintransit    numeric(24,6),-- r5dwtmpparts.ztp_qtytorepairintransit%TYPE,
@rNPart_ztp_qtyatshop               numeric(24,6),-- r5dwtmpparts.ztp_qtyatshop%TYPE,
@rNPart_ztp_qtyatsupplier           numeric(24,6),-- r5dwtmpparts.ztp_qtyatsupplier%TYPE,
@rNPart_ztp_price                   numeric(24,6),-- r5dwtmpparts.ztp_price%TYPE,
@rNPart_ztp_corevalue               numeric(24,6) -- r5dwtmpparts.ztp_corevalue%TYPE
declare @bPriceUpdated bit
declare @nEarlierTrans int --number = 0
declare @nReturn int
declare  @nZtp_price		numeric(24,6)
declare  @nDebugOldPrice   	numeric(24,6)  --number
declare  @nDebugOldQtyOnHand 	numeric(24,6)  --number
declare  @nDebugOldQtyToRepair 	numeric(24,6)  --number
declare  @nDebugOldQtyInTransit numeric(24,6)  --number
declare  @nDebugOldQtyToRepairInTransit numeric(24,6)      --number
declare  @sRPPRCCAL nvarchar(30)
declare @bRPPRCCAL bit
declare @sDebugFirstTime nvarchar(30)
declare @bDebugFirstTime bit
declare @sGpriceLevel nvarchar(200)
declare @sPrintString nvarchar(4000)

	--run initialization code if necessary
	execute @nReturn = O7DWETLDM_PACKAGE_INIT
	if @@ERROR <> 0 or @nReturn <> 0
	begin
		return -1
	end
	--run initialization code if necessary
	execute @nReturn = O7DWETL_PACKAGE_INIT
	if @@ERROR <> 0 or @nReturn <> 0
	begin
		return -1
	end

	set @bPriceUpdated = 1
        select @rSPart_ztp_part = ztp_part,
           @rSPart_ztp_partorg =   ztp_partorg,
           @rSPart_ztp_store =   ztp_store,
           @rSPart_ztp_storeorg =    ztp_storeorg,
           @rSPart_ztp_partclass =    ztp_partclass,
           @rSPart_ztp_partclassorg =    ztp_partclassorg,
           @rNPart_ztp_qtyonhand =    ztp_qtyonhand,
           @rNPart_ztp_qtytorepair =    ztp_qtytorepair,
           @rNPart_ztp_qtyintransit =    ztp_qtyintransit,
           @rNPart_ztp_qtytorepairintransit =    ztp_qtytorepairintransit,
           @rNPart_ztp_qtyatshop =    ztp_qtyatshop,
           @rNPart_ztp_qtyatsupplier =    ztp_qtyatsupplier,
           @rNPart_ztp_price =    ztp_price,
           @rNPart_ztp_corevalue =    ztp_corevalue
    from   r5dwtmpparts
    where  ztp_part     = @rSTransaction_trl_part
    and    ztp_partorg  = @rSTransaction_trl_part_org
    and    ztp_store    = @rSTransaction_trl_store
    and    ztp_storeorg = @rSTransaction_str_org
    if @@ROWCOUNT = 0
        return

      -- Save old values for debug purposes
    if @bDebug = 0 
	begin
        set @nDebugOldPrice                = @rNPart_ztp_price
        set @nDebugOldQtyOnHand            = @rNPart_ztp_qtyonhand
        set @nDebugOldQtyToRepair          = @rNPart_ztp_qtytorepair
        set @nDebugOldQtyInTransit         = @rNPart_ztp_qtyintransit
        set @nDebugOldQtyToRepairInTransit = @rNPart_ztp_qtytorepairintransit
    end

    if @rNTransaction_trl_io <> 0 and @rSTransaction_trl_store is not null
	begin
        if @rSTransaction_trl_rtype in ('RECV', N'RETN')
		begin
			execute @nReturn = GET_PACKAGE_VARIABLE N'O7DWETLDM', N'RPPRCCAL', @sRPPRCCAL OUTPUT
			if @@ERROR <> 0 or @nReturn <> 0
				return -1
			if @sRPPRCCAL LIKE 'Y%'
				set @bRPPRCCAL = 0
			else
				set @bRPPRCCAL = 1
            if @rSTransaction_tra_fromrentity <> N'EVNT' or @bRPPRCCAL = 0
			begin
				execute @nReturn = O7DWETLDM_UPDATEPRICE  @rNPart_ztp_qtyonhand               ,											
									  @rNPart_ztp_price                   ,											
									  @rNTransaction_trl_price            ,
									  @rNTransaction_trl_qty              ,
									  @rNTransaction_trl_io               ,
									  @rNTransaction_orl_contractdiscount ,
									  @rNTransaction_orl_totextracost     ,
									  @rNTransaction_orl_tottaxcost      -- ,

				if @@ERROR <> 0  or @nReturn <>  0
					return -1
                --updatePrice(part, trans)
                set @bPriceUpdated = 0
            end 

            if @rSTransaction_trl_rtype = N'RECV' and @rSTransaction_trl_order is not null and
               @rSTransaction_orl_rtype = N'RE'
            begin
                set @rNPart_ztp_qtytorepair = @rNTransaction_trl_qty + isnull(@rNTransaction_trl_scrapqty, 0)
            end
        end

        if @rSTransaction_trl_rtype = N'CORR' 
			begin
				select   @nZtp_price = trl_price
				from     r5translines
				where    cast(trl_trans as numeric(38,0)) < cast(@rSTransaction_tra_code as numeric(38,0))
				and      dbo.F_TRUNC_DATE(trl_date,'DD') <= dbo.F_TRUNC_DATE(@rDTransaction_trl_date,'DD')
				and      trl_store = @rSTransaction_trl_store
				and      trl_part  = @rSTransaction_trl_part
				and      trl_part_org = @rSTransaction_trl_part_org
				and      trl_rtype = N'I'
				and      trl_price is not null
				order by trl_date de


