CREATE PROCEDURE dbo.O7DWETLDM_UPDATEPRICE 	   @rNPart_ztp_qtyonhand               numeric(24,6),-- r5dwtmpparts.ztp_qtyonhand%TYPE,
					   @rNPart_ztp_price                   numeric(24,6),-- r5dwtmpparts.ztp_price%TYPE,
					   @rNTransaction_trl_price            numeric(24,6), --r5translines.trl_price%TYPE,
					   @rNTransaction_trl_qty              numeric(24,6), --r5translines.trl_qty%TYPE,
					   @rNTransaction_trl_io               numeric(18,0), --r5translines.trl_io%TYPE,
					   @rNTransaction_orl_contractdiscount numeric(24,6),  --number,
					   @rNTransaction_orl_totextracost     numeric(24,6),  --number,
					   @rNTransaction_orl_tottaxcost       numeric(24,6)--,  --number,
AS
SET NOCOUNT ON
declare @nPartQty      numeric(24,6)  --number
declare @nPartVal      numeric(24,6)  --number
declare @nTransQty     numeric(24,6)  --number
declare @nTransVal     numeric(24,6)  --number
begin
    set @nPartQty  = @rNPart_ztp_qtyonhand
    set @nPartVal  = @nPartQty * @rNPart_ztp_price
    set @nTransQty = @rNTransaction_trl_qty * @rNTransaction_trl_io
    set @nTransVal = (@nTransQty * @rNTransaction_trl_price * @rNTransaction_orl_contractdiscount) +
                      @rNTransaction_orl_totextracost + @rNTransaction_orl_tottaxcost

    if @nPartQty - @nTransQty > 0
	begin
        set @rNPart_ztp_price = round((@nPartVal - @nTransVal) / (@nPartQty - @nTransQty), 6)
    end

end


