	@nValue		numeric(24,6) OUTPUT,
	@nSlope     numeric(24,6) OUTPUT,
	@nLslope    numeric(24,6) OUTPUT,
	@nAslope    numeric(24,6) OUTPUT

AS 
	SET NOCOUNT ON
	declare @sFormula			nvarchar(8)		--r5minmaxformparam.fop_formula%TYPE
	declare @sValue				nvarchar(2000)		--r5minmaxformulas.mmf_formula%TYPE
	declare @sParam				nvarchar(2000)		--r5minmaxformulas.mmf_formula%TYPE
	declare @nFirst				int
	declare @sX					nvarchar(1)
	declare @sStatement			nvarchar(2000)		--r5minmaxparameters.mmp_statement%TYPE
	declare @sTempStatement		nvarchar(2000)		--r5minmaxparameters.mmp_statement%TYPE
	declare @sFormu				nvarchar(2000)		--r5minmaxformulas.mmf_formula%TYPE
	declare @sFOP_Uom			nvarchar(30)		--r5minmaxformparam.fop_uom%TYPE
	declare @sMMP_Uom			nvarchar(30)		--r5minmaxparameters.mmp_uom%TYPE
	declare @nCursor1			int
	declare @nIgnore			int
	declare @sResult			nvarchar(500)
	declare @nResult			float
	declare @nConv				numeric(24,6)
	declare @nPos$				int
	declare @sChk				nvarchar(4)
	declare @sMMFCode			nvarchar(8)
	declare @sMMFFormula		nvarchar(2000)
	declare @sPROType			nvarchar(4)
	declare @sAPMColumn			nvarchar(35)
	declare @sMMPUom			nvarchar(30)
	declare @sMMPStatement		nvarchar(2000)
	declare @sFOPUom			nvarchar(30)
	declare @nFirst1			int
	declare @nFirst2			int
	declare @nFirst3			int
	declare @nFirst4			int
	declare @nFirst5			int
	declare @nFirst6			int
	declare @nCount				int
	declare @sStatement1			nvarchar(2000)
	declare @sStatement2			nvarchar(2000)
	declare @sStatement3			nvarchar(2000)

	DECLARE cAPM CURSOR local FOR   SELECT mmf_code,
											 mmf_formula,
											 apm_column,
											 pro_type
										FROM   r5minmaxformulas,
											 r5properties,
											 r5aspectprompts
										WHERE  apm_prompt = pro_code
										AND    mmf_code   = CASE @sAction WHEN N'INS' THEN apm_insert ELSE apm_update END 
										AND    apm_aspect = @nAspect
										AND    pro_type  IN ( N'NUM', N'CHAR' )
										ORDER BY apm_seq 

	OPEN cAPM
	FETCH NEXT FROM cAPM INTO @sMMFCode, @sMMFFormula, @sAPMColumn, @sPROType
	WHILE @@FETCH_STATUS = 0
		begin
			set @sFormula = @sMMFCode
			set @sFormu   = @sMMFFormula
			IF @sFormula IS NOT NULL 
				begin
					set @sValue = @sFormu

					WHILE charindex( N'$', @sValue ) > 0 
						begin
							/* Get all parameters */
							set @nPos$  = CHARINDEX( N'$', @sValue ) 
							set @sValue = SUBSTRING( @sValue, @nPos$ + 1, len(@sValue) - @nPos$ + 1 )
							if LEN( @sValue ) > 0
								begin 

									set @nFirst1 = CASE CHARINDEX( N' ', @sValue ) WHEN 0 THEN 1000 ELSE CHARINDEX( N' ', @sValue ) END
									set @nFirst2 = CASE CHARINDEX( N')', @sValue ) WHEN 0 THEN 1000 ELSE CHARINDEX( N')', @sValue ) END
									set @nFirst3 = CASE CHARINDEX( N'+', @sValue ) WHEN 0 THEN 1000 ELSE CHARINDEX( N'+', @sValue ) END
									set @nFirst4 = CASE CHARINDEX( N'-', @sValue ) WHEN 0 THEN 1000 ELSE CHARINDEX( N'-', @sValue ) END
									set @nFirst5 = CASE CHARINDEX( N'/', @sValue ) WHEN 0 THEN 1000 ELSE CHARINDEX( N'/', @sValue ) END
									set @nFirst6 = CASE CHARINDEX( N'*', @sValue ) WHEN 0 THEN 1000 ELSE CHARINDEX( N'*', @sValue ) END

									set @nFirst = CASE  WHEN @nFirst1 < @nFirst2 and @nFirst1 < @nFirst3 and @nFirst1 < @nFirst4 and @nFirst1 < @nFirst5 and @nFirst1 < @nFirst6 then @nFirst1 
														WHEN @nFirst2 < @nFirst1 and @nFirst2 < @nFirst3 and @nFirst2 < @nFirst4 and @nFirst2 < @nFirst5 and @nFirst2 < @nFirst6 then @nFirst2 
														WHEN @nFirst3 < @nFirst1 and @nFirst3 < @nFirst2 and @nFirst3 < @nFirst4 and @nFirst3 < @nFirst5 and @nFirst3 < @nFirst6 then @nFirst3 
														WHEN @nFirst4 < @nFirst1 and @nFirst4 < @nFirst2 and @nFirst4 < @nFirst3 and @nFirst4 < @nFirst5 and @nFirst4 < @nFirst6 then @nFirst4 
														WHEN @nFirst5 < @nFirst1 and @nFirst5 < @nFirst2 and @nFirst5 < @nFirst3 and @nFirst5 < @nFirst4 and @nFirst5 < @nFirst6 then @nFirst5
														ELSE @nFirst6 END


									set @sParam = SUBSTRING( @sValue, 1, @nFirst - 1 )
									set @sStatement = null
									set @sResult    = null

									Select @nCount = count(*)
									FROM   r5minmaxparameters,
									r5minmaxformparam
									WHERE  fop_parameter = mmp_code
									AND    fop_parameter = @sParam
									AND    fop_formula   = @sFormula

									If @nCount > 0 
										SELECT @sFOP_Uom = fop_uom, 
										@sMMP_Uom = mmp_uom, 
										@sStatement = mmp_statement
										FROM   r5minmaxparameters,
										r5minmaxformparam
										WHERE  fop_parameter = mmp_code
										AND    fop_parameter = @sParam
										AND    fop_formula   = @sFormula
									else
										set @sChk = N'1'	

									IF @sStatement IS NOT NULL 
