CREATE PROCEDURE O7FLXPKG_O7FLXTST
                 @sStatement    NVARCHAR(MAX)
                ,@sErrorMessage NVARCHAR(255) OUTPUT
                ,@sCheck        NVARCHAR(4)   OUTPUT
AS
BEGIN
/*****************************************************************************************************************************************/
/* 08/27/2003 Milind Patil                                                                                                               */
/* The only purpose of this procedure is to parse the given statement and check if it is a valid statement without executing it. However */
/* since parsing a statement without executing is not possible in SQL Server procedure/trigger/function, this will have to be done on the*/
/* client side that calls this procedure. Instead of calling this procedure, the client can set the PARSEONLY option on, execute the     */
/* the statement, check the error and again reset the PARSEONLY option off. The PARSEONLY option can not be set/reset within a procedure */
/* or a trigger or a function.                                                                                                           */
/*****************************************************************************************************************************************/

SET NOCOUNT ON
SET @sCheck = N'1'
SET @sErrorMessage = N'SQL Server stored procedure can not validate a statement. This needs to be done by client. Please see the detailed '
                   + N'note on how to do this in the comments in O7FLXPKG_O7FLXTST code'
END


