CREATE PROCEDURE O7FORGETME_ASSOCIATEDDATA
  @pk         NVARCHAR( 30 ),
  @entity     NVARCHAR( 6 ),
  @code       NVARCHAR( 255 ),
  @newcode    NVARCHAR( 30 ),
  @errorfound NVARCHAR( 1 ) OUTPUT
AS
  DECLARE @updstat    NVARCHAR( 1000 )
BEGIN
  /* Comments. */
  SET @updstat = 'UPDATE r5addetails SET add_code = ''' + @newcode + ''' WHERE add_rentity = ''' + @entity + ''' AND add_code = ''' + @code + ''''
  EXECUTE o7forgetme_executeupdate @pk, 10, @updstat, @errorfound OUTPUT
  /* Custom Fields. */
  SET @updstat = 'UPDATE r5propertyvalues SET prv_code = ''' + @newcode + ''' WHERE prv_rentity = ''' + @entity + ''' AND prv_code = ''' + @code + ''''
  EXECUTE o7forgetme_executeupdate @pk, 20, @updstat, @errorfound OUTPUT
  /* Addresses. */
  SET @updstat = 'UPDATE r5address SET adr_code = ''' + @newcode + ''' WHERE adr_rentity = ''' + @entity + ''' AND adr_code = ''' + @code + ''''
  EXECUTE o7forgetme_executeupdate @pk, 30, @updstat, @errorfound OUTPUT
  /* Documents. */
  SET @updstat = 'UPDATE r5docentities SET dae_code = ''' + @newcode + ''' WHERE dae_rentity = ''' + @entity + ''' AND dae_code = ''' + @code + ''''
  EXECUTE o7forgetme_executeupdate @pk, 40, @updstat, @errorfound OUTPUT
  /* Parts. */
  SET @updstat = 'UPDATE r5entityparts SET epa_code = ''' + @newcode + ''' WHERE epa_rentity = ''' + @entity + ''' AND epa_code = ''' + @code + ''''
  EXECUTE o7forgetme_executeupdate @pk, 50, @updstat, @errorfound OUTPUT
END


