  DECLARE @eventlocation         NVARCHAR( 30 )
  DECLARE @eventlocorg           NVARCHAR( 15 )
  DECLARE @eventperson           NVARCHAR( 15 )
  DECLARE @eventschedgrp         NVARCHAR( 30 )
  DECLARE @eventcostcode         NVARCHAR( 30 )
  DECLARE @cnt                   NUMERIC
