  DECLARE @ecsobjperson          NVARCHAR( 15 )
  DECLARE @ecsorgcommon          NVARCHAR( 1 )
  DECLARE @parconfigcode         NVARCHAR( 30 )
  DECLARE @parconfigorg          NVARCHAR( 15 )
  DECLARE @parconfigrev          NUMERIC( 4 )
  DECLARE @parcode               NVARCHAR( 30 )

  /* Determine organization. */
  IF   @allspecific       = N'+'   -- All equipment must be specific.
    OR @orgcommon         = N'-'   -- Equipment Configuration is specific. 
    OR @objconfigspecific = N'+'   -- Equipment Configuration is flagged to use specific. 
    /* Use ( always specific ) session org. */
    SET @eqorg = @egsorg
  ELSE
    /* Use ( common ) org of equipment configuration. */
    SET @eqorg = @egsequipconfigorg

  /* Location is blank, when object goes in store or is dependent. */
  IF @ucorcode IN ( N'A', N'C' ) OR @dependent = N'+'
    BEGIN
      SET @eqloc    = NULL
      SET @eqlocorg = NULL
    END  
  ELSE
    BEGIN
      SET @eqloc    = @egslocation
      SET @eqlocorg = @egslocationorg
    END

  /* Determine department. */
  IF @mrccommon = N'-' AND @mrcorg <> @eqorg
    /* Session equipment department not allowed, use config department. */
    SET @eqmrc = @objmrc
  ELSE
    SET @eqmrc = ISNULL( @egsmrc, @objmrc )

  /* Determine costcode. */
  IF @cstcommon = N'-' AND @cstorg <> @eqorg 
    /* Session equipment costcode not allowed, use config costcode. */
    SET @eqcostcode = @objcostcode
  ELSE
    SET @eqcostcode = ISNULL( @egscostcode, @objcostcode )

  /* Determine person. */
  IF @percommon = N'-' AND @perorg <> @eqorg
    /* Session equipment person not allowed, use config person. */
    SET @eqperson = @objperson
  ELSE
    SET @eqperson = ISNULL( @egsperson, @objperson )

  /* Check whether there are PMs attached. */
  SELECT @cnt = COUNT( * )
  FROM  r5equipconfigpms
  WHERE egp_object     = @object
  AND   egp_object_org = @egsequipconfigorg
  IF @cnt > 0 AND @egspms = N'+'
