  ELSE   
    SET @mpattached = N'-'

  /* Determine WO data. */
  IF @pmattached = N'-' AND @mpattached = N'-'
    BEGIN
      /* If no PMs and no MPs associated, then there is no need to have WO/event data. */
      SET @eventlocation = NULL
      SET @eventlocorg   = NULL
      SET @eventmrc      = NULL
      SET @eventschedgrp = NULL
      SET @eventcostcode = NULL
    END  
  ELSE
    BEGIN
      SET @eventlocation = ISNULL( @egseventlocation, @egslocation )
      SET @eventlocorg   = ISNULL( @egseventlocorg, @egslocationorg )
      SET @eventschedgrp = @egseventschedgrp
      SET @eventmrc      = ISNULL( @egseventmrc, @eqmrc )
      SET @eventperson   = ISNULL( @egseventperson, @eqperson )
      SET @eventcostcode = ISNULL( @egseventcostcode, @eqcostcode )
    END

  /* Retrieve PK. */
  EXECUTE @return = r5o7_o7maxseq @pk OUTPUT, N'CSD', N'1', @chk OUTPUT

  INSERT INTO r5ecsessiondetails( csd_pk, csd_parentpk, csd_session, csd_equipconfig, csd_equipconfig_org, csd_equipconfigrev, csd_object, csd_level, 
          csd_dependent, csd_costrollup, csd_syslevel, csd_asmlevel, csd_complevel, csd_complocation, csd_parentec, csd_parentec_org, 
          csd_parentecrev, csd_parentobject, csd_org, csd_location, csd_location_org, csd_mrc, csd_costcode, csd_person, csd_event_org, 
          csd_pmattached, csd_mpattached, csd_eventmrc, csd_eventlocation, csd_eventlocation_org, csd_eventperson, csd_eventschedgrp, 
          csd_eventcostcode, csd_equipmentcreated )
  VALUES( @pk, @parentpk, @sessionid, @equipconfig, @equipconfigorg, @equipconfigrev, @object, @stclevel, 
          ISNULL( @parentdependent, @dependent ), ISNULL( @parentcostrollup, @costrollup ), @syslevel, @asmlevel, @complevel, @complocation, @parentec, @parentecorg, 
          @parentecrev, @parentobject, @eqorg, @eqloc, @eqlocorg, @eqmrc, @eqcostcode, @eqperson, @egsorg, 
          @pmattached,  @mpattached, @eventmrc, @eventlocation, @eventlocorg, @eventperson, @eventschedgrp, 
          @eventcostcode, N'-' )

  IF @toplevel


