create function o7getfuturepolinevalue (@sTempSessionId	numeric, @sTempSequence numeric)
returns numeric(24,6)
AS
BEGIN
	declare 
	@nResult numeric(24,6),
	@pretotal numeric(24,6),
	@contracttotal numeric(24,6), 
	@discountpercent numeric(10,4), 
	@discountvalue numeric(24,6) = 0, 
	@taxpercent numeric(10,4), 
	@taxvalue numeric(24,6) = 0, 
	@exch numeric(24,12) = 1, 
	@linetype nvarchar(4), 
	@invccurr nvarchar(10), 
	@org nvarchar(15), 
	@curr nvarchar(30), 
	@store nvarchar(30), 
	@supplier nvarchar(30), 
	@supplierorg nvarchar(15),
	@part nvarchar(30), 
	@partorg nvarchar(15),
	@multiply numeric(10,4), 
	@price numeric(24,6) = 0, 
	@qty numeric(24,6), 
	@contract nvarchar(30),
	@today date,
	@nCount int;


	/* Get INVCCURR install param value */
	SELECT @invccurr = COALESCE( ins_desc, 'ON' )
	FROM   r5install
	WHERE  ins_code = 'INVCCURR';

	/* Calculate pretax, prediscount total value, get additional values */
	SELECT @pretotal = COALESCE(tro_price, 0)*COALESCE(tro_qty, 0)
	FROM r5tempreqsfororder
	WHERE tro_sessionid = @sTempSessionId 
	AND tro_sequence = @sTempSequence

	SELECT @exch = COALESCE(tro_exch, 1)
	FROM r5tempreqsfororder
	WHERE tro_sessionid = @sTempSessionId 
	AND tro_sequence = @sTempSequence

	SELECT @linetype =  tro_rtype
	FROM r5tempreqsfororder
	WHERE tro_sessionid = @sTempSessionId 
	AND tro_sequence = @sTempSequence

   IF @linetype <> 'PS' AND @linetype <> 'PD' AND @linetype <> 'RE' 
   BEGIN
	   /* Calculate total value taking into account exchange rate, if applicable */  
	   IF @invccurr <> 'ON' 
		BEGIN 
			SET @nResult =  COALESCE(@exch, 1) * @pretotal
		END
		ELSE
		BEGIN
			SET @nResult = @pretotal
		END
   END
   ELSE 
   BEGIN
	   /* Calculate discount and total value with discount, if any */
		SELECT @store = tro_store, @supplier = tro_supplier, @supplierorg = tro_supplier_org, 
		@org = tro_org, @today = dbo.o7gttime2(tro_org), @curr = tro_curr, @part = tro_part, @partorg = tro_part_org, @qty = tro_qty
		FROM r5tempreqsfororder
		WHERE tro_sessionid = @sTempSessionId 
		AND tro_sequence = @sTempSequence;

		while 1=1
			begin					
				select @nCount = count(*)
				FROM  r5contracts c,
					  r5conparts p
				WHERE  c.con_supplier     = @supplier
				AND    c.con_supplier_org = @supplierorg
				AND    ISNULL( c.con_store, 'x' ) LIKE ISNULL( @store, 'x' )
				AND    c.con_org          = @org
				AND    c.con_rstatus      = N'A'
				AND    c.con_start       <= @today 
				AND    c.con_end         >= @today 
				AND    c.con_curr         = @curr
				AND    p.cpa_contract     = c.con_code
				AND    p.cpa_part         = @part
				AND    p.cpa_part_org     = @partorg

				if @nCount > 0 
					begin
						SELECT @contract = c.con_code,
							  @price = p.cpa_price,
							  @multiply = p.cpa_multiply
						FROM  r5contracts    c,
							  r5conparts     p
						WHERE  c.con_supplier     = @supplier
						AND    c.con_supplier_org = @supplierorg
						AND    c.con_org          = @org
						AND    ISNULL( c.con_store, 'x' ) LIKE ISNULL( @store, 'x' )
						AND    c.con_rstatus      = N'A'
						AND    c.con_start       <= @today
						AND    c.con_end         >= @today
						AND    c.con_curr         = @curr
						AND    p.cpa_contract     = c.con_code
						AND    p.cpa_part         = @part
						AND    p.cpa_part_org     = @partorg

						SELECT @contracttotal = @price * @qty / COALESCE(@multiply, 1)

						SELECT @discountpercent = MAX(cdi_disperc)
						FROM   r5condiscounts
						WHERE  cdi_contract = @contract 
						AND    cdi_part     = @part
						AND    cdi_part_org = @partorg
						AND    cdi_rtype    = N'Q'
						AND  ( cdi_value   <= cast( @contracttotal as numeric(24,6) ) OR
							  cdi_purqty  <= cast( @qty as numeric(24,6)) )

						SET @discountpercent = 0.01 * COALESCE(@discountpercent, 0)
						SET @discountvalue = @contracttotal * @discountpercent
						SET @pretotal = @contracttotal - @discountvalue
						BREAK;
					end	
				else
					begin
						SELECT @store = str_parent
						FROM   r5stores
						WHERE  str_code = @store
						BREAK;
					end		
			end

	   /* Calculate tax and total value with discount and tax, if any */    
	   SELECT @taxpercent = dbo.o7gettax(par_tax, dbo.o7gttime2(tro_org))
	   FROM r5tempreqsfororder, r5parts
	   WHERE tro_sessionid = @sTempSessionId 
	   AND tro_sequence = @sTempSequence
	   AND par_code = tro_part 
	   AND par_org = tro_part_org;

	   SET @taxpercent = 0.01 * COALESCE(@taxpercent, 0);
	   SET @taxvalue = @pretotal * @taxpercent;
	   SET @pretotal = @pretotal + CAST(@taxvalue AS numeric(24,2)); -- rounded to 2 decimals to match the existing PO generation calculations

		/* Calculate total value taking into account exchange rate, if applicable */  
		IF @invccurr <> 'ON'
		BEGIN
			SET @nResult =  COALESCE(@exch, 1) * @pretotal;
		END
		ELSE
		BEGIN
			SET @nResult = @pretotal;
		END
	END
   RETURN (CAST(COALESCE(@nResult, 0) AS NUMERIC(24,6)));
END

create function O7GETJOBTRADEDETAILS( 
  @sEvent NVARCHAR(30),
  @sParentActivity NUMERIC(8),
  @sShiftSchedulingSession NUMERIC(18),
  @sEmployee NVARCHAR(15),
  @sDescLanguage NVARCHAR(2),
  @sField NVARCHAR(15))
returns NVARCHAR(80)
as
begin
   declare @sCount NUMERIC(8)
   declare @sTrade  NVARCHAR(15)
   declare @sPlannedTrade NVARCHAR(80)
   declare @sMainResource NVARCHAR(1)
   declare @nReturn NVARCHAR(80)

   SELECT @sCount = COUNT(*) FROM r5activities, r5actschedules WHERE act_event = acs_event AND COALESCE(act_parent,act_act) = acs_activity 
   AND COALESCE(act_parent,act_act) = @sParentActivity AND act_event = @sEvent AND act_trade IS NOT NULL AND acs_responsible = @sEmployee AND (CASE WHEN @sShiftSchedulingSession > 0 THEN @sShiftSchedulingSession ELSE 0 END = COALESCE(acs_shiftschedulesession,0));

   IF @sCount = 1
    BEGIN
         SELECT @sTrade = act_trade 
         FROM r5activities, r5actschedules WHERE act_event = acs_event AND COALESCE(act_parent,act_act) = acs_activity 
         AND COALESCE(act_parent,act_act) = @sParentActivity AND act_event = @sEvent AND act_seq IS NULL AND acs_responsible = @sEmployee AND (CASE WHEN @sShiftSchedulingSession > 0 THEN @sShiftSchedulingSession ELSE 0 END = COALESCE(acs_shiftschedulesession,0));

         SELECT @sPlannedTrade = COALESCE(trd_abbreviation, dbo.r5o7_o7get_desc(@sDescLanguage,'TRAD', trd_code, null, null)) FROM r5trades WHERE trd_code = @sTrade;

         SET @sMainResource = '+';
    END    
    ELSE 
        BEGIN
             SELECT @sCount = COUNT(*) 
             FROM r5activities, r5actschedules WHERE act_event = acs_event AND COALESCE(act_parent,act_act) = acs_activity 
             AND COALESCE(act_parent,act_act) = @sParentActivity AND act_event = @sEvent AND act_seq IS NULL AND acs_responsible = @sEmployee AND (CASE WHEN @sShiftSchedulingSession > 0 THEN @sShiftSchedulingSession ELSE 0 END = COALESCE(acs_shiftschedulesession,0));

             IF @sCount = 1
                BEGIN
                 SELECT @sTrade = acs_trade 
                 FROM r5activities, r5actschedules WHERE act_event = acs_event AND COALESCE(act_parent,act_act) = acs_activity 
                 AND COALESCE(act_parent,act_act) = @sParentActivity AND act_event = @sEvent AND act_seq IS NULL AND acs_responsible = @sEmployee AND (CASE WHEN @sShiftSchedulingSession > 0 THEN @sShiftSchedulingSession ELSE 0 END = COALESCE(acs_shiftschedulesession,0));
                 SET @sMainResource = '-';
                 SET @sPlannedTrade = '';
                END
            ELSE 
                BEGIN 
                 SELECT @sTrade = per_trade FROM r5personnel WHERE per_code = @sEmployee;
                  SET @sMainResource = '-';
                 SET @sPlannedTrade = '';
                END
        END

   IF @sField = 'TRADE'
      set @nReturn = @sTrade
   ELSE IF @sField = 'PLANNEDTRADE'
      set @nReturn = @sPlannedTrade 
   ELSE IF @sField = 'MAINRESOURCE'
      set @nReturn = @sMainResource 
   ELSE 
      set @nReturn = NULL

   RETURN @nReturn
end
