  @nOutputrangeto   numeric(24,6),
  @nOutputrangefrom numeric(24,6),
  @nDevicerangeto   numeric(24,6),
  @nDevicerangefrom numeric(24,6),
  @nPrecision       numeric(24,6),
  @sOutputcalctype  nvarchar(4) )
returns numeric(24,6)
as
begin
	declare @nReturnvalue numeric(24,6)
	if @sOutputcalctype = 'LINR'
		/* linear */		
		set @nReturnvalue = ( ( ( @nOutputrangeto - @nOutputrangefrom ) / ( @nDevicerangeto - @nDevicerangefrom ) ) * @nTestpoint ) + 
			( @nOutputrangeto - ( ( @nOutputrangeto - @nOutputrangefrom ) / ( @nDevicerangeto - @nDevicerangefrom ) ) * @nDevicerangeto )
	else if @sOutputcalctype = 'SQRT'
		/* Square root */
		set @nReturnvalue = @nOutputrangefrom + ( sign( @nTestpoint - @nDevicerangefrom ) * 
								( sqrt( abs( @nTestpoint - @nDevicerangefrom ) / ( @nDevicerangeto - @nDevicerangefrom ) ) ) * 
								( @nOutputrangeto - @nOutputrangefrom ) )
	else
		set @nReturnvalue = @nOutput

    return round( @nReturnvalue, isnull( @nPrecision, 100 ) )
end
