CREATE PROCEDURE O7GREEN_DELETEDATA
  @sInv       NVARCHAR(45), 
  @sInvOrg    NVARCHAR(15), 
  @nSeq       NUMERIC(6),
  @sObj       NVARCHAR(30), 
  @sObjOrg    NVARCHAR(15), 
  @sCom       NVARCHAR(15),
  @sSup       NVARCHAR(30), 
  @sSupOrg    NVARCHAR(15), 
  @dFromDate  DATETIME,     
  @dToDate    DATETIME,     
  @sCalcAvg   NVARCHAR(1), 
  @sBillBased NVARCHAR(1)
AS 
  SET NOCOUNT ON
  /* Delete records belonging to the current invoice. */
  DELETE FROM r5utilityrates 
  WHERE  utr_calculatedaverage = COALESCE( @sCalcAvg, utr_calculatedaverage )
  AND    utr_invoice     = @sInv
  AND    utr_invoice_org = @sInvOrg
  AND    utr_sequence    = @nSeq
  AND    utr_billbased   = COALESCE( @sBillBased, utr_billbased )

  IF @sSup IS NOT NULL
    /* Delete old extrapolation records. */
    DELETE FROM r5utilityrates
    WHERE  utr_supplier     = @sSup
    AND    utr_supplier_org = @sSupOrg
    AND    utr_commodity    = @sCom
    AND    utr_object       = @sObj
    AND    utr_object_org   = @sObjOrg
    AND    utr_billbased    = N'-'
    AND    utr_calculatedaverage = N'-'   

  /* Also delete sum records. */
  DELETE FROM r5utilityrates 
  WHERE  utr_date BETWEEN @dFromDate AND @dToDate
  AND    utr_calculatedaverage = N'+'
  AND    utr_object     = @sObj
  AND    utr_object_org = @sObjOrg
  AND    utr_commodity  = @sCom

  /* And also co2emission records. */
  DELETE FROM r5commodityco2emission
  WHERE  cce_date BETWEEN @dFromDate AND @dToDate
  AND    cce_object     = @sObj
  AND    cce_object_org = @sObjOrg
  AND    cce_commodity  = @sCom

  /* And then also energy efficiency records. */
  DELETE FROM r5commodityenergyeff
  WHERE  cee_date BETWEEN @dFromDate AND @dToDate
  AND    cee_object     = @sObj
  AND    cee_object_org = @sObjOrg
  AND    cee_commodity  = @sCom
  AND    cee_origin     = N'U'


