create procedure O7GTDUAL2 
	@sCurr			nvarchar(4),
	@nValue			float,
	@nTodual		NUMERIC(24,12) OUTPUT,
	@nFromdual		NUMERIC(24,12) OUTPUT,
	@nExch			NUMERIC(24,12) OUTPUT,
	@sOrdorg		nvarchar(15),
	@sTimeOrg		nvarchar(15) 

as
	SET NOCOUNT ON
	DECLARE	@dExchdate		datetime
	declare @nReturn		int

	execute @nReturn = O7GTTIME @dExchdate OUTPUT, @sTimeOrg
	if @@ERROR <> 0 or @nReturn <> 0
		return -1

	execute @nReturn = O7GTDUAL @sCurr, @nValue, @nTodual OUTPUT, @nFromdual OUTPUT, @nExch OUTPUT, @sOrdorg, @dExchdate
	if @@ERROR <> 0 or @nReturn <> 0
		return -1


